import numpy as np

class Logged:  # wraps an ndarray, reports which NumPy calls hit it
    def __init__(self, data):
        self.data = np.asarray(data)
    def __array__(self, dtype=None, copy=None):
        return self.data if dtype is None else self.data.astype(dtype)
    def __array_ufunc__(self, ufunc, method, *inputs, **kw):
        args = [i.data if isinstance(i, Logged) else i for i in inputs]
        print("ufunc:", ufunc.__name__, method)
        return Logged(getattr(ufunc, method)(*args, **kw))
    def __array_function__(self, func, types, args, kwargs):
        print("function:", func.__name__)
        args = [a.data if isinstance(a, Logged) else a for a in args]
        return func(*args, **kwargs)

x = Logged([1.0, 2.0, 3.0])
y = np.sqrt(x)              # ufunc: sqrt __call__
print(np.mean(y))           # function: mean, then 1.382...
print(np.asarray(x) * 2)    # [2. 4. 6.]

a = np.ones(3)
xp = a.__array_namespace__()  # NumPy's array-API namespace
print(xp.sum(a))              # 3.0
